/**
 * Returns length for line segments (MoveTo, LineTo).
 *
 * @param x1 the starting point X
 * @param y1 the starting point Y
 * @param x2 the ending point X
 * @param y2 the ending point Y
 * @returns the line segment length
 */
const getLineLength = (x1: number, y1: number, x2: number, y2: number): number => {
  const dx = x1 - x2;
  const dy = y1 - y2;
  return Math.sqrt(dx * dx + dy * dy);
};

/**
 * Returns a point along the line segments (MoveTo, LineTo).
 *
 * @param x1 the starting point X
 * @param y1 the starting point Y
 * @param x2 the ending point X
 * @param y2 the ending point Y
 * @param distance the distance to point in [0-1] range
 * @returns the point at length
 */
const getPointAtLineLength = (
  x1: number,
  y1: number,
  x2: number,
  y2: number,
  distance?: number,
): { x: number; y: number } => {
  let point = { x: x1, y: y1 };

  /* istanbul ignore else */
  if (typeof distance === "number") {
    const length = getLineLength(x1, y1, x2, y2);
    if (distance <= 0) {
      point = { x: x1, y: y1 };
    } else if (distance >= length) {
      point = { x: x2, y: y2 };
    } else {
      const ratio = distance / length;
      point = { x: x1 + (x2 - x1) * ratio, y: y1 + (y2 - y1) * ratio };
    }
  }
  return point;
};

/**
 * Returns bounding box for line segments (MoveTo, LineTo).
 *
 * @param x1 the starting point X
 * @param y1 the starting point Y
 * @param x2 the ending point X
 * @param y2 the ending point Y
 * @returns the bounding box for line segments
 */
const getLineBBox = (
  x1: number,
  y1: number,
  x2: number,
  y2: number,
): [number, number, number, number] => {
  const { min, max } = Math;

  return [min(x1, x2), min(y1, y2), max(x1, x2), max(y1, y2)] as [number, number, number, number];
};

/** The tools for line segment computation. */
const lineTools = {
  getLineBBox,
  getLineLength,
  getPointAtLineLength,
};

export { getLineBBox, getLineLength, getPointAtLineLength, lineTools };
